/* Sect alliances, missions, and the armory */
.sect-choice-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:15px}
.sect-choice{position:relative;display:flex;flex-direction:column;align-items:flex-start;min-width:0;padding:14px;border:1px solid #e8e8df;border-radius:8px;background:#fffefa}
.sect-choice.selected{border-color:#9bb9a0;background:linear-gradient(145deg,#f1f6ed,#fffefa);box-shadow:inset 0 0 0 1px rgba(90,133,98,.12)}
.sect-choice .tech-seal,.gear-card .tech-seal{width:35px;height:35px;margin-bottom:8px;font-size:19px}
.sect-choice h3,.mission-row h3,.gear-card h3{margin:0 0 5px;font:600 13px var(--serif);color:#354b3f}
.sect-choice p,.mission-row p,.gear-card p{flex:1;margin:0 0 11px;color:#7c887f;font-size:9px;line-height:1.5}
.sect-choice .action-btn{width:100%;padding:8px 6px;white-space:normal}
.mission-row{display:flex;flex-direction:column;align-items:flex-start;margin-top:10px;padding:13px;border:1px solid #e8e8df;border-radius:7px;background:#fffefa}
.mission-row small{margin:0 0 10px;color:#8a7952;font-size:8px;line-height:1.5}
.mission-row .action-btn{align-self:stretch;white-space:normal}
.gear-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:14px}
.gear-card{display:flex;flex-direction:column;align-items:flex-start;min-width:0;padding:13px;border:1px solid #e8e8df;border-radius:7px;background:#fffefa}
.gear-card .tech-seal{background:#f2efe4;color:#927c4f;border-color:#e7dfca}
.gear-card p{min-height:28px}
.gear-card .tech-level{min-height:22px;margin:0 0 8px;font-size:7px;letter-spacing:.55px}
.gear-card .action-btn{width:100%;min-height:34px;padding:7px 5px;white-space:normal;line-height:1.35}
.sect-spell{background:#eef4eb!important;border-color:#d7e5d7!important;color:#3d7259!important}
.sect-spell:hover{background:#e2efe2!important;border-color:#a9c8ac!important}
@media(max-width:720px){.sect-choice-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.gear-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:390px){.sect-choice{padding:11px}.sect-choice h3{font-size:12px}.sect-choice-grid{gap:8px}.gear-grid{gap:8px}.gear-card{padding:10px}.gear-card h3{font-size:12px}.gear-card p{font-size:8px}}

