const fs = require('fs');
const vm = require('vm');
const assert = require('assert');
const source = fs.readFileSync('game.js', 'utf8').replace(
  'render(); setInterval(tick, 1000);',
  'window.__test = { state, renderPaths, trainPath, attemptBreak, seekEnemy, buyGear, startTrip, collectTrip, realms, realmProgress, gateNeeds, requirement, realmTitle, render }; render(); setInterval(tick, 1000);'
);
function makeGame(saved = null, { now = 2_000_000_000_000, random = 0 } = {}) {
  const storage = new Map();
  if (saved) storage.set('stillwater-cultivator-v1', JSON.stringify(saved));
  const elements = new Map();
  const makeClassList = () => ({ add(){}, remove(){}, toggle(){}, contains(){ return false; } });
  const el = (id) => {
    if (!elements.has(id)) elements.set(id, { id, style: {}, dataset: {}, classList: makeClassList(), textContent: '', innerHTML: '', hidden: false, disabled: false, addEventListener(){}, querySelector(){ return { textContent: '' }; } });
    return elements.get(id);
  };
  const document = { getElementById: el, querySelectorAll(){ return []; }, addEventListener(){}, body: { classList: makeClassList() } };
  const window = { addEventListener(){}, scrollTo(){} };
  class FakeDate extends Date { static now(){ return now; } }
  const math = Object.create(Math); math.random = () => random;
  const context = { document, window, localStorage: { getItem(k){ return storage.get(k) ?? null; }, setItem(k,v){ storage.set(k,v); } }, Date: FakeDate, Math: math, setTimeout(){ return 1; }, clearTimeout(){}, setInterval(){ return 1; }, console, Object, Array, Number, String, JSON, Infinity };
  vm.runInNewContext(source, context, { filename: 'game.js' });
  return { api: window.__test, storage, elements };
}

// Realm floor naming and badge use the configured nine-floor Immortal realm.
const names = makeGame();
for (let stage = 1; stage <= 33; stage++) {
  const progress = names.api.realmProgress(stage);
  assert(progress.floor >= 1 && progress.floor <= progress.floors, `stage ${stage} floor stays in realm bounds`);
  assert(names.api.realmTitle(stage).endsWith(` ${progress.floor}`), `stage ${stage} title matches floor`);
}
assert.equal(names.api.realmTitle(28), 'Immortal 4');
assert.equal(names.api.realmTitle(33), 'Immortal 9');

// Same-day offline progress adds only elapsed time, not time since day start.
const now = 2_000_000_000_000;
const sameDay = makeGame({ totalSeconds: 100, dailyDate: 1, qiToday: 70, medSeconds: 10, active: true, lastSeen: now - 20_000 }, { now });
assert(Math.abs(sameDay.api.state.qiToday - (70 + 20 * .88)) < 1e-8);
assert.equal(sameDay.api.state.medSeconds, 30);
// Crossing a day resets daily counters and retains only time elapsed in the new day.
const crossed = makeGame({ totalSeconds: 290, dailyDate: 1, qiToday: 70, medSeconds: 10, active: true, lastSeen: now - 20_000 }, { now });
assert(Math.abs(crossed.api.state.qiToday - (10 * .88)) < 1e-8);
assert.equal(crossed.api.state.medSeconds, 10);

// Failed breakthrough keeps gate ingredients; successful breakthrough consumes them.
const failedGate = makeGame({ stage: 9, qi: 100000, pathProgress: { qi: 9, body: 3 }, pathLevels: { body: 3, spirit: 0 }, herbs: { root: 1, flower: 0 } }, { random: .999 });
failedGate.api.attemptBreak();
assert.equal(failedGate.api.state.stage, 9);
assert.equal(failedGate.api.state.herbs.root, 1);
assert.equal(failedGate.api.state.qi, 80000);

// Frontier journey pays the loot advertised by the expedition card.
const frontier = makeGame({ stage: 25, trip: { id: 'frontier', ends: now - 1, reward: 100 }, herbs: { herb: 0, root: 0, flower: 0 } }, { now });
frontier.api.collectTrip();
assert.equal(frontier.api.state.herbs.root, 3);
assert.equal(frontier.api.state.herbs.flower, 3);
assert.equal(frontier.api.state.completedTrips, 1);

// Unlock boundaries enforce no spending before unlock and permit purchases on it.
const beforeGear = makeGame({ stage: 9, sectTokens: 99 });
beforeGear.api.buyGear('helmet');
assert.equal(beforeGear.api.state.equipment.helmet.owned, false);
assert.equal(beforeGear.api.state.sectTokens, 99);
const atGear = makeGame({ stage: 10, sectTokens: 99 });
atGear.api.buyGear('helmet');
assert.equal(atGear.api.state.equipment.helmet.owned, true);
assert.equal(atGear.api.state.sectTokens, 93);

console.log('PASS realm floors/titles, same-day and cross-day offline counters, failed-gate resource retention, frontier loot, gear unlock boundary');

